content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;
  background-color: #050510;
  color: #ffffff;
  overflow-x: hidden;
}

/* スクロールバーのカスタムスタイリング（宇宙観テーマに調和） */
::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}

::-webkit-scrollbar-track {
  background: rgba(10, 10, 25, 0.5);
}

::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.2);
  border-radius: 3px;
}

::-webkit-scrollbar-thumb:hover {
  background: rgba(255, 255, 255, 0.4);
}

.app-container {
  position: relative;
  width: 100vw;
  height: 100vh;
  display: flex;
  flex-direction: column;
  background: radial-gradient(circle at center, #1b1b3a 0%, #050510 100%);
}

.header {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  padding: 20px;
  display: flex;
  flex-direction: column;
  align-items: center;
  z-index: 10;
  pointer-events: none;
}

.title {
  font-size: 2rem;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: #ffffff;
  text-shadow: 0 0 10px rgba(255, 255, 255, 0.5), 0 0 20px rgba(100, 150, 255, 0.3);
  margin-bottom: 4px;
}

.subtitle {
  font-size: 0.9rem;
  color: #a0a0c0;
  letter-spacing: 1px;
}

.canvas-container {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 1;
}

.info-panel {
  position: absolute;
  top: 100px;
  right: 20px;
  width: 320px;
  background: rgba(15, 15, 35, 0.85);
  backdrop-filter: blur(10px);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 12px;
  padding: 20px;
  z-index: 10;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);
  animation: fadeIn 0.3s ease-in-out;
  will-change: transform, opacity;
}

.info-title {
  font-size: 1.4rem;
  font-weight: 600;
  margin-bottom: 12px;
  color: #61dafb;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  padding-bottom: 8px;
}

.info-desc {
  font-size: 0.95rem;
  line-height: 1.6;
  color: #d0d0e0;
}

.controls {
  position: absolute;
  bottom: 80px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  gap: 10px;
  z-index: 10;
  background: rgba(15, 15, 35, 0.7);
  backdrop-filter: blur(8px);
  padding: 10px 20px;
  border-radius: 30px;
  border: 1px solid rgba(255, 255, 255, 0.1);
}

.btn {
  background: rgba(255, 255, 255, 0.1);
  color: #ffffff;
  border: 1px solid rgba(255, 255, 255, 0.2);
  padding: 8px 16px;
  border-radius: 20px;
  cursor: pointer;
  font-size: 0.9rem;
  transition: all 0.2s ease;
}

.btn:hover {
  background: rgba(255, 255, 255, 0.25);
  border-color: rgba(255, 255, 255, 0.4);
  transform: translateY(-2px);
}

.btn:active {
  transform: translateY(0);
}

.planet-list {
  position: absolute;
  bottom: 140px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  gap: 8px;
  z-index: 10;
  max-width: 90vw;
  overflow-x: auto;
  padding: 5px;
}

.planet-btn {
  background: rgba(10, 10, 25, 0.8);
  color: #b0b0d0;
  border: 1px solid rgba(255, 255, 255, 0.1);
  padding: 6px 12px;
  border-radius: 16px;
  cursor: pointer;
  font-size: 0.85rem;
  white-space: nowrap;
  transition: all 0.2s ease;
}

.planet-btn:hover {
  background: rgba(40, 40, 80, 0.8);
  color: #ffffff;
}

.footer-note {
  position: absolute;
  bottom: 15px;
  left: 0;
  width: 100%;
  text-align: center;
  font-size: 0.8rem;
  color: #707090;
  z-index: 10;
  pointer-events: none;
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (max-width: 768px) {
  .header {
    padding: 10px;
  }
  .title {
    font-size: 1.3rem;
  }
  .subtitle {
    font-size: 0.75rem;
  }
  .info-panel {
    top: auto;
    bottom: 135px;
    right: 10px;
    left: 10px;
    width: auto;
    max-height: 22vh;
    overflow-y: auto;
    padding: 12px;
  }
  .info-title {
    font-size: 1.1rem;
    margin-bottom: 6px;
  }
  .info-desc {
    font-size: 0.85rem;
  }
  .planet-list {
    bottom: 75px;
  }
  .controls {
    bottom: 20px;
    padding: 6px 12px;
  }
}

export type PlanetId = 
  | 'mercury'
  | 'venus'
  | 'earth'
  | 'mars'
  | 'jupiter'
  | 'saturn'
  | 'uranus'
  | 'neptune';

export interface CelestialBody {
  readonly id: PlanetId;
  readonly name: string;
  readonly japaneseName: string;
  readonly color: string;
  readonly size: number;
  readonly distance: number;
  readonly speed: number;
  readonly radius: number;
  readonly description: string;
}

export type PlanetData = CelestialBody;

import { useRef, memo } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import { OrbitControls, Stars } from '@react-three/drei';
import * as THREE from 'three';
import { PlanetData } from './types';

interface SunProps {
  onSelect: () => void;
  isSelected: boolean;
}

const Sun = ({ onSelect, isSelected }: SunProps) => {
  const meshRef = useRef<THREE.Mesh>(null);

  useFrame((_, delta) => {
    if (meshRef.current) {
      meshRef.current.rotation.y += delta * 0.1;
    }
  });

  return (
    <group onClick={(e) => { e.stopPropagation(); onSelect(); }}>
      <mesh ref={meshRef}>
        <sphereGeometry args={[2.5, 32, 32]} />
        <meshStandardMaterial 
          color="#ffaa00" 
          emissive="#ff5500"
          emissiveIntensity={isSelected ? 0.8 : 0.3}
          roughness={0.2}
        />
      </mesh>
      {/* 太陽の光彩効果 */}
      <pointLight intensity={2.5} distance={150} decay={1} color="#ffffff" />
    </group>
  );
};

interface PlanetMeshProps {
  planet: PlanetData;
  speedMultiplier: number;
  isSelected: boolean;
  onSelect: (planet: PlanetData) => void;
}

const Planet = memo(({ planet, speedMultiplier, isSelected, onSelect }: PlanetMeshProps) => {
  const planetRef = useRef<THREE.Group>(null);
  const meshRef = useRef<THREE.Mesh>(null);
  const angleRef = useRef(Math.random() * Math.PI * 2);

  useFrame((_, delta) => {
    if (planetRef.current) {
      angleRef.current += planet.speed * 0.2 * speedMultiplier * delta;
      const x = Math.cos(angleRef.current) * planet.distance;
      const z = Math.sin(angleRef.current) * planet.distance;
      planetRef.current.position.set(x, 0, z);
    }
    if (meshRef.current) {
      meshRef.current.rotation.y += delta * 0.5;
    }
  });

  return (
    <>
      {/* 軌道線 */}
      <mesh rotation={[-Math.PI / 2, 0, 0]}>
        <ringGeometry args={[planet.distance - 0.03, planet.distance + 0.03, 64]} />
        <meshBasicMaterial color="#ffffff" transparent opacity={0.15} side={THREE.DoubleSide} />
      </mesh>

      <group ref={planetRef}>
        <mesh 
          ref={meshRef} 
          onClick={(e) => { e.stopPropagation(); onSelect(planet); }}
        >
          <sphereGeometry args={[planet.size, 32, 32]} />
          <meshStandardMaterial 
            color={planet.color} 
            roughness={0.7}
            metalness={0.2}
            emissive={isSelected ? new THREE.Color(planet.color) : new THREE.Color(0x000000)}
            emissiveIntensity={isSelected ? 0.5 : 0}
          />
        </mesh>
        {/* 土星の輪の改良された表現 */}
        {planet.id === 'saturn' && (
          <mesh rotation={[Math.PI / 3, 0, 0]}>
            <ringGeometry args={[planet.size * 1.3, planet.size * 2.4, 64]} />
            <meshStandardMaterial 
              color="#d4b583" 
              side={THREE.DoubleSide} 
              transparent 
              opacity={0.85} 
              roughness={0.5}
            />
          </mesh>
        )}
      </group>
    </>
  );
});

Planet.displayName = 'Planet';

interface SolarSystemProps {
  planets: PlanetData[];
  selectedPlanet: PlanetData | null;
  speedMultiplier: number;
  onSelectPlanet: (planet: PlanetData | null) => void;
}

export default function SolarSystem({ planets, selectedPlanet, speedMultiplier, onSelectPlanet }: SolarSystemProps) {
  return (
    <div className="canvas-container">
      <Canvas camera={{ position: [0, 30, 50], fov: 60 }}>
        <color attach="background" args={['#050510']} />
        <ambientLight intensity={0.4} />
        <Stars radius={100} depth={50} count={5000} factor={4} saturation={0} fade speed={1} />

        {/* 太陽 */}
        <Sun onSelect={() => onSelectPlanet(null)} isSelected={selectedPlanet === null} />

        {/* 惑星たち */}
        {planets.map((planet) => (
          <Planet
            key={planet.id}
            planet={planet}
            speedMultiplier={speedMultiplier}
            isSelected={selectedPlanet?.id === planet.id}
            onSelect={onSelectPlanet}
          />
        ))}

        <OrbitControls enablePan={true} enableZoom={true} enableRotate={true} minDistance={5} maxDistance={150} />
      </Canvas>
    </div>
  );
}

import { useState } from 'react';
import SolarSystem from './SolarSystem';
import { PlanetData } from './types';
import { PLANETS, SUN_DATA } from './constants';
import './index.css';

export default function App() {
  const [selectedPlanet, setSelectedPlanet] = useState<PlanetData | null>(null);
  const [speedMultiplier, setSpeedMultiplier] = useState<number>(1);
  const [prevSpeed, setPrevSpeed] = useState<number>(1);

  const handleSelectPlanet = (planet: PlanetData | null) => {
    setSelectedPlanet(planet);
  };

  const handleTogglePause = () => {
    if (speedMultiplier === 0) {
      setSpeedMultiplier(prevSpeed > 0 ? prevSpeed : 1);
    } else {
      setPrevSpeed(speedMultiplier);
      setSpeedMultiplier(0);
    }
  };

  const currentInfo = selectedPlanet
    ? {
        title: `${selectedPlanet.japaneseName} (${selectedPlanet.name})`,
        description: (
          <>
            {selectedPlanet.description}
            <br /><br />
            <strong>半径:</strong> 約 {selectedPlanet.radius.toLocaleString()} km<br />
            <strong>太陽からの距離:</strong> 単位距離 {selectedPlanet.distance} AU
          </>
        )
      }
    : {
        title: `${SUN_DATA.japaneseName} (${SUN_DATA.name})`,
        description: SUN_DATA.description
      };

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">太陽系 3D シミュレーション</h1>
        <p className="subtitle">惑星をクリックするか選択して詳細情報を確認できます</p>
      </header>

      <SolarSystem 
        planets={PLANETS}
        selectedPlanet={selectedPlanet}
        speedMultiplier={speedMultiplier}
        onSelectPlanet={handleSelectPlanet}
      />

      {/* 惑星選択リスト */}
      <div className="planet-list">
        <button 
          className="planet-btn" 
          onClick={() => handleSelectPlanet(null)}
        >
          太陽
        </button>
        {PLANETS.map((planet) => (
          <button
            key={planet.id}
            className="planet-btn"
            onClick={() => handleSelectPlanet(planet)}
          >
            {planet.japaneseName}
          </button>
        ))}
      </div>

      {/* 速度変更コントロール */}
      <div className="controls">
        <button className="btn" onClick={handleTogglePause}>
          {speedMultiplier === 0 ? '再生' : '停止'}
        </button>
        <button className="btn" onClick={() => setSpeedMultiplier(0.5)}>0.5x</button>
        <button className="btn" onClick={() => setSpeedMultiplier(1)}>1x</button>
        <button className="btn" onClick={() => setSpeedMultiplier(3)}>3x</button>
        <button className="btn" onClick={() => setSpeedMultiplier(10)}>10x</button>
      </div>

      {/* 詳細情報パネル */}
      <div className="info-panel">
        <h2 className="info-title">{currentInfo.title}</h2>
        <p className="info-desc">{currentInfo.description}</p>
      </div>

      <div className="footer-note">
        マウスドラッグで視点回転・ズームが可能 | React Three Fiber & Three.js
      </div>
    </div>
  );
}
